/bin/bash -lc "python - <<'PY'
import requests
for repo in ['scikit-learn','scikit_learn','sklearn-pandas','numpy']:
    try:
        r=requests.get(f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/', params={'limit':10,'onlyActiveTags':'true'}, timeout=20)
        print('repo', repo, 'status', r.status_code)
        if r.ok:
            print([t.get('name') for t in r.json().get('tags', [])[:10]])
    except Exception as e:
        print('repo', repo, 'error', type(e).__name__, e)
PY"
